params.script:
// Extract tools from MCP response
const mcpResult = input.result;
let tools = [];

if (mcpResult && mcpResult.result && mcpResult.result.tools) {
  tools = mcpResult.result.tools;
} else if (mcpResult && mcpResult.tools) {
  tools = mcpResult.tools;
}

console.log("Available tools:", tools.map(t => t.name).join(', '));

// Get user request
const userRequest = input.request || input.query || input.task || '';
const userParams = input.parameters || input.params || {};

if (!userRequest) {
  return {
    error: "No user request provided",
    availableTools: tools,
    usage: "Provide a 'request' field describing what you want to accomplish"
  };
}

console.log("User request:", userRequest);

// Simple keyword-based tool selection
// In a real implementation, you might use an LLM here
const requestLower = userRequest.toLowerCase();
let selectedTools = [];
let executionPlan = [];

// Tool selection logic based on keywords
tools.forEach(tool => {
  const toolName = tool.name.toLowerCase();
  const toolDesc = (tool.description || '').toLowerCase();

  // Check if tool name or description matches request keywords
  const keywords = [
    toolName,
    ...toolName.split('_'),
    ...toolDesc.split(' ')
  ].filter(k => k.length > 2);

  const relevanceScore = keywords.reduce((score, keyword) => {
    if (requestLower.includes(keyword)) {
      return score + 1;
    }
    return score;
  }, 0);

  if (relevanceScore > 0) {
    selectedTools.push({
      tool: tool,
      relevanceScore: relevanceScore,
      matchedKeywords: keywords.filter(k => requestLower.includes(k))
    });
  }
});

// Sort by relevance score
selectedTools.sort((a, b) => b.relevanceScore - a.relevanceScore);

// Create execution plan
if (selectedTools.length === 0) {
  // Fallback: suggest similar tools
  const suggestions = tools.filter(t => {
    const name = t.name.toLowerCase();
    return requestLower.split(' ').some(word => 
      word.length > 2 && (name.includes(word) || word.includes(name.split('_')[0]))
    );
  }).slice(0, 3);

  return {
    error: "No matching tools found for request",
    request: userRequest,
    availableTools: tools,
    suggestions: suggestions.map(t => t.name),
    hint: "Try requests like: 'get weather', 'search web', 'get time', etc."
  };
}

// Limit to top 3 most relevant tools
const topTools = selectedTools.slice(0, 3);

executionPlan = topTools.map((item, index) => ({
  toolName: item.tool.name,
  tool: item.tool,
  relevanceScore: item.relevanceScore,
  matchedKeywords: item.matchedKeywords,
  parameters: userParams,
  order: index + 1
}));

return {
  request: userRequest,
  availableTools: tools,
  selectedTools: topTools.map(t => t.tool),
  executionPlan: executionPlan,
  planSummary: {
    totalAvailable: tools.length,
    selected: executionPlan.length,
    topMatches: executionPlan.map(p => `${p.toolName} (score: ${p.relevanceScore})`)
  },
  currentIndex: 0,
  executionResults: [],
  ready: true
};

const currentIndex = input.currentIndex || 0;
const executionPlan = input.executionPlan || [];

if (currentIndex >= executionPlan.length) {
  return {
    ...input,
    allComplete: true,
    message: "All planned tools executed"
  };
}

const currentPlan = executionPlan[currentIndex];
const toolParams = currentPlan.parameters || {};

// Smart parameter inference based on tool name and user request
const inferredParams = { ...toolParams };
const request = input.request || '';
const requestLower = request.toLowerCase();

// Common parameter inference patterns
if (currentPlan.toolName.includes('weather') && !inferredParams.location) {
  // Try to extract location from request
  const locationMatch = request.match(/(?:in|for|at)\s+([A-Za-z\s]+?)(?:\s|$|,|\.)/i);
  if (locationMatch) {
    inferredParams.location = locationMatch[1].trim();
  } else {
    inferredParams.location = 'San Francisco'; // default
  }
}

if (currentPlan.toolName.includes('search') && !inferredParams.query) {
  // Use the original request as search query
  inferredParams.query = request;
}

if (currentPlan.toolName.includes('time') && !inferredParams.timezone) {
  inferredParams.timezone = 'UTC';
}

console.log(`Executing tool ${currentIndex + 1}/${executionPlan.length}: ${currentPlan.toolName}`);
console.log('Parameters:', JSON.stringify(inferredParams, null, 2));

return {
  ...input,
  currentPlan: currentPlan,
  toolName: currentPlan.toolName,
  toolParameters: JSON.stringify(inferredParams),
  executionReady: true
};

const currentIndex = input.currentIndex || 0;
const executionResults = input.executionResults || [];
const currentPlan = input.currentPlan;

// Record this execution
const result = {
  toolName: currentPlan.toolName,
  success: true,
  result: input.result,
  relevanceScore: currentPlan.relevanceScore,
  matchedKeywords: currentPlan.matchedKeywords,
  parameters: JSON.parse(input.toolParameters || '{}'),
  executedAt: new Date().toISOString(),
  order: currentPlan.order
};

executionResults.push(result);

// Prepare for next iteration
const nextIndex = currentIndex + 1;

return {
  ...input,
  executionResults: executionResults,
  currentIndex: nextIndex,
  lastResult: result
};

const currentIndex = input.currentIndex || 0;
const executionResults = input.executionResults || [];
const currentPlan = input.currentPlan;

// Record this execution failure
const result = {
  toolName: currentPlan.toolName,
  success: false,
  error: input.error || "Execution failed",
  relevanceScore: currentPlan.relevanceScore,
  matchedKeywords: currentPlan.matchedKeywords,
  parameters: JSON.parse(input.toolParameters || '{}'),
  executedAt: new Date().toISOString(),
  order: currentPlan.order
};

executionResults.push(result);

// Continue with next tool despite error
const nextIndex = currentIndex + 1;

return {
  ...input,
  executionResults: executionResults,
  currentIndex: nextIndex,
  lastResult: result
};

const executionResults = input.executionResults || [];
const successful = executionResults.filter(r => r.success);
const failed = executionResults.filter(r => !r.success);

// Create a natural language summary
let summary = `I processed your request: "${input.request}"\n\n`;

if (successful.length > 0) {
  summary += `Successfully executed ${successful.length} tool(s):\n`;
  successful.forEach((result, i) => {
    summary += `${i + 1}. ${result.toolName} - ${result.success ? 'Success' : 'Failed'}\n`;
    if (result.result && result.result.result) {
      const resultData = typeof result.result.result === 'string' 
        ? result.result.result 
        : JSON.stringify(result.result.result, null, 2);
      summary += `   Result: ${resultData.substring(0, 200)}${resultData.length > 200 ? '...' : ''}\n`;
    }
  });
}

if (failed.length > 0) {
  summary += `\nFailed executions (${failed.length}):\n`;
  failed.forEach((result, i) => {
    summary += `${i + 1}. ${result.toolName} - Error: ${result.error}\n`;
  });
}

return {
  success: true,
  request: input.request,
  summary: summary,
  executionStats: {
    totalExecuted: executionResults.length,
    successful: successful.length,
    failed: failed.length,
    planSummary: input.planSummary
  },
  results: executionResults,
  availableTools: input.availableTools,
  completedAt: new Date().toISOString()
};

return {
  success: false,
  request: input.request || 'No request provided',
  error: input.error || "No suitable tools found for your request",
  availableTools: (input.availableTools || []).map(t => t.name),
  suggestions: input.suggestions || [],
  hint: input.hint || "Try describing what you want to accomplish",
  timestamp: new Date().toISOString()
};

return {
  success: false,
  error: "MCP operation failed: " + (input.error || "Unknown error"),
  timestamp: new Date().toISOString()
};
